package hp.common.security;
import org.junit.*;import static org.junit.Assert.*;import java.util.*;import java.lang.reflect.*;import hp.Final.service.MemberServiceImpl;import hp.Final.dao.*;import org.springframework.mock.web.*;import org.springframework.ui.ExtendedModelMap;import org.springframework.web.servlet.mvc.support.RedirectAttributesModelMap;
public class NativeAuthenticationTest {
 static class Accounts extends MemberDAO {Map<String,Object> saved;public int checkId(String id){return saved!=null&&id.equals(saved.get("ID"))?1:0;}public void insertMember(Map<String,Object> p){saved=new HashMap<String,Object>(p);saved.put("IDX",1);}public Map<String,Object> login(Map<String,Object> p){return saved!=null&&saved.get("ID").equals(p.get("ID"))?new HashMap<String,Object>(saved):null;}}
 @Test public void registrationLoginHashAndReservedRole()throws Exception{Accounts dao=new Accounts();MemberServiceImpl service=new MemberServiceImpl();Field f=MemberServiceImpl.class.getDeclaredField("memberDAO");f.setAccessible(true);f.set(service,dao);Map<String,Object> p=new HashMap<String,Object>();p.put("ID","patient");p.put("PWD","GoodPassword123!");p.put("NAME","Synthetic");service.insertMember(p,new RedirectAttributesModelMap());assertTrue(String.valueOf(dao.saved.get("PWD")).startsWith("pbkdf2$600000$"));Map<String,Object> login=new HashMap<String,Object>();login.put("ID","patient");login.put("PWD","GoodPassword123!");MockHttpSession session=new MockHttpSession();service.login(login,session,new ExtendedModelMap(),new MockHttpServletResponse(),new RedirectAttributesModelMap());assertEquals("patient",session.getAttribute("ID"));login.put("PWD","wrong");MockHttpSession other=new MockHttpSession();service.login(login,other,new ExtendedModelMap(),new MockHttpServletResponse(),new RedirectAttributesModelMap());assertNull(other.getAttribute("ID"));p.put("ID","admin");p.put("PWD","GoodPassword123!");try{service.insertMember(p,new RedirectAttributesModelMap());fail();}catch(SecurityException expected){}}
 @Test public void mapperNameCannotBeSelectedByClient()throws Exception{HpListDAO dao=new HpListDAO();Map<String,Object> p=new HashMap<String,Object>();for(String query:new String[]{"member.login","secure.lockReset","hplist.selectAdminHpList","invalid"}){p.put("QUERY",query);try{dao.selectBoardList(p);fail(query);}catch(SecurityException expected){}}}
}
